<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
import CostChart from './CostChart.vue'
const $q = useQuasar(), active = ref('licenses'), loading = ref(false), data = ref(null), projects = ref([])
const filters = reactive({ start: '', end: '', projectId: '', attribution: 'all', affiliateId: '' })
const headers = () => ({ headers: { Authorization: 'Bearer ' + localStorage.getItem('aito_admin_token') } })
const money = cents => (Number(cents || 0) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
const panels = [{ id: 'projects', label: 'Projetos', icon: 'mdi-folder-star-outline' }, { id: 'licenses', label: 'Licenças do kit', icon: 'mdi-shield-key-outline' }, { id: 'costs', label: 'Custos internos', icon: 'mdi-cash-minus' }, { id: 'affiliates', label: 'Afiliados', icon: 'mdi-account-star-outline' }]
const attributionOptions = [{ label: 'Todas as vendas', value: 'all' }, { label: 'Sem afiliados', value: 'direct' }, { label: 'Com afiliados', value: 'affiliate' }]
const summary = computed(() => data.value?.kit || {})
const rows = computed(() => active.value === 'projects' ? data.value?.projects.rows || [] : active.value === 'costs' ? data.value?.costs.rows || [] : active.value === 'affiliates' ? data.value?.ranking || [] : data.value?.sales || [])
const columns = computed(() => {
  if (active.value === 'affiliates') return [{ name: 'affiliate', label: 'Afiliado', field: r => r.affiliate?.name, align: 'left' }, { name: 'sales', label: 'Vendas', field: 'sales', sortable: true }, { name: 'amount', label: 'Faturamento', field: r => money(r.amountCents) }, { name: 'commission', label: 'Comissão', field: r => money(r.commissionCents) }]
  if (['projects', 'costs'].includes(active.value)) return [{ name: 'title', label: 'Descrição', field: 'title', align: 'left' }, { name: 'project', label: 'Projeto', field: r => r.projectId?.title || 'Geral', align: 'left' }, { name: 'amount', label: 'Valor original', field: r => Number(r.amount).toLocaleString('pt-BR', { style: 'currency', currency: r.currency }) }, { name: 'date', label: active.value === 'projects' ? 'Emissão da nota paga' : 'Data do lançamento', field: r => new Date(r.issueDate || r.date || r.updatedAt).toLocaleDateString('pt-BR') }]
  return [{ name: 'customer', label: 'Cliente', field: r => r.customer?.name || r.customerName || 'Cliente', align: 'left' }, { name: 'source', label: 'Origem', field: r => ({ site: 'Site', whatsapp: 'WhatsApp', manual: 'Manual' })[r.source], align: 'left' }, { name: 'coupon', label: 'Cupom / afiliado', field: r => r.couponCode ? r.couponCode + ' · ' + (r.affiliate?.name || '') : 'Venda direta', align: 'left' }, { name: 'amount', label: 'Valor pago', field: r => r.amountCents == null ? 'Não informado' : money(r.amountCents) }, { name: 'commission', label: 'Comissão', field: r => money(r.commissionCents) }, { name: 'date', label: 'Data', field: r => new Date(r.paidAt).toLocaleDateString('pt-BR') }]
})
const top = computed(() => active.value === 'projects' ? [{ label: 'Faturamento de projetos', value: money(data.value?.projects.totalCents) }, { label: 'Notas fiscais pagas', value: rows.value.length }] : active.value === 'costs' ? [{ label: 'Custos internos cadastrados', value: money(data.value?.costs.totalCents) }, { label: 'Lançamentos ativos', value: rows.value.length }] : active.value === 'affiliates' ? [{ label: 'Vendas com afiliados', value: money(summary.value.affiliateCents) }, { label: 'Comissões a distribuir', value: money(summary.value.commissionCents) }, { label: 'Afiliados com vendas', value: rows.value.length }] : [{ label: 'Faturamento de licenças', value: money(summary.value.totalCents) }, { label: 'Vendas sem afiliados', value: money(summary.value.directCents) }, { label: 'Vendas com afiliados', value: money(summary.value.affiliateCents) }, { label: 'Após comissões', value: money(summary.value.afterCommissionCents) }])
async function load() { loading.value = true; try { data.value = (await api.get('/admin/business-dashboard', { ...headers(), params: filters })).data.data } catch (e) { $q.notify({ type: 'negative', message: e.response?.data?.message || 'Não foi possível carregar o dashboard.' }) } finally { loading.value = false } }
onMounted(async () => { await load(); try { projects.value = (await api.get('/admin/projects', headers())).data.data || [] } catch { /* Project selector remains optional. */ } })
</script>
<template>
  <section class="business"><header><div><small>VISÃO DO NEGÓCIO</small><h1>Resultados que contam.</h1><p>Projetos, produto e parceiros, cada um com seu recorte.</p></div><q-btn outline no-caps icon="mdi-refresh" label="Atualizar" :loading="loading" @click="load"/></header>
    <q-tabs v-model="active" no-caps align="left" active-color="teal-9" indicator-color="teal-7" class="business-tabs"><q-tab v-for="p in panels" :key="p.id" :name="p.id" :label="p.label" :icon="p.icon"/></q-tabs>
    <q-form class="business-filters" @submit.prevent="load"><q-input v-model="filters.start" outlined dense type="date" label="De" stack-label/><q-input v-model="filters.end" outlined dense type="date" label="Até" stack-label/><q-select v-if="['projects','costs'].includes(active)" v-model="filters.projectId" clearable outlined dense label="Projeto" :options="projects.map(p=>({label:p.title,value:p._id}))" emit-value map-options/><template v-else><q-select v-model="filters.attribution" outlined dense label="Origem da venda" :options="attributionOptions" emit-value map-options/><q-select v-model="filters.affiliateId" outlined dense clearable label="Afiliado" :options="(data?.affiliates||[]).map(p=>({label:p.name,value:p._id}))" emit-value map-options/></template><q-btn unelevated color="teal-8" no-caps type="submit" label="Filtrar" :loading="loading"/></q-form>
    <div class="business-stats"><article v-for="card in top" :key="card.label"><span>{{ card.label }}</span><strong>{{ card.value }}</strong></article></div>
    <q-banner v-if="summary.unknownCount && ['licenses','affiliates'].includes(active)" rounded class="business-note">{{ summary.unknownCount }} licença(s) sem valor informado. Os totais incluem somente valores registrados; edite os valores em Clientes.</q-banner>
    <div v-if="active==='licenses' && data?.monthly.length" class="business-charts"><CostChart light title="Vendas diretas e afiliadas (R$)" :labels="['Sem afiliados','Com afiliados']" :values="[summary.directCents/100,summary.affiliateCents/100]" :colors="['#159d7c','#d9b664']"/><CostChart light title="Faturamento mensal (R$)" type="bar" :labels="data.monthly.map(m=>m.month)" :values="data.monthly.map(m=>(m.directCents+m.affiliateCents)/100)" :colors="['#14977b']"/></div>
    <p v-if="active==='projects'" class="business-caption">Faturamento reconhecido pelas notas de projetos com status “pago”, no período de emissão. Não inclui propostas ou notas em aberto.</p><p v-if="active==='costs'" class="business-caption">Custos da empresa com status ativo, filtrados pela data do lançamento. Valores recorrentes aparecem uma vez por cadastro; esta visão não é projeção.</p><p v-if="['projects','costs'].includes(active) && data?.exchangeRate" class="business-caption">Totais em real · US$ 1 = {{data.exchangeRate.rate}} · {{data.exchangeRate.source}} · {{data.exchangeRate.date}}</p>
    <q-table :key="active" flat bordered wrap-cells row-key="_id" :rows="rows" :columns="columns" :loading="loading" :pagination="{rowsPerPage:10}" no-data-label="Nenhum registro neste período"/>
    <p v-if="data?.truncated" class="business-caption">A tabela mostra até 1.000 vendas recentes. Os totais consideram todo o período.</p>
  </section>
</template>
<style scoped src="./business-dashboard-layout.css"></style>
<style scoped>.business{display:grid;gap:22px;color:#163e32}.business>header{display:flex;gap:18px;align-items:center;justify-content:space-between}.business h1{font-size:clamp(25px,3vw,36px);line-height:1.2;font-weight:780;margin:9px 0}.business p{margin:0;color:#608174;font-size:13px;line-height:1.7}.business small{font-size:10px;letter-spacing:.15em;color:#148168;font-weight:800}.business-tabs{background:#e7f5ee;border-radius:14px}.business-filters{display:flex;gap:10px;flex-wrap:wrap;align-items:start}.business-filters>.q-field{flex:1;min-width:145px}.business-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.business-stats article{display:grid;gap:15px;padding:23px;border:1px solid #cce6d8;background:linear-gradient(135deg,#fff,#ebf8f1);border-radius:17px}.business-stats span{color:#628173;font-size:12px}.business-stats strong{color:#0c6c53;font-size:27px;font-weight:800}.business-note{background:#fff5d9;color:#7c621d;font-size:12px}.business-charts{display:grid;grid-template-columns:1fr 1.6fr;gap:18px}.business :deep(.cost-chart){color:#23483c;background:#f7fcf9;border:1px solid #cee4d8}.business :deep(.cost-chart__head){color:#356454}.business-caption{font-size:11px!important}.business :deep(.q-table__container){background:#fff;border-color:#d4e8dd;color:#264b3e;border-radius:14px}.business :deep(.q-field__control){background:#fff}.business :deep(.q-field__native),.business :deep(.q-field__label){color:#315b4c}@media(max-width:700px){.business-charts{grid-template-columns:1fr}.business>header{align-items:start}.business>header>.q-btn{font-size:11px}.business-stats{grid-template-columns:1fr 1fr}.business-stats article{padding:16px}.business-stats strong{font-size:21px}}</style>
